    map-underscore-to-camel-case: true
    jdbc-type-for-null: NULL
management:
  endpoints:
    web:
      exposure:
        include: health,info,prometheus
  endpoint:
    health:
      show-details: never
claims:
  workflow:
    definition: classpath:config/workflow.yml
    maximum-information-cycles: 3
    appeal-period: ${CLAIMS_APPEAL_PERIOD:P30D}
  security:
    member-ownership-enabled: true
    allow-development-users: ${CLAIMS_ALLOW_DEVELOPMENT_USERS:false}
  outbox:
    dispatch-delay-ms: 1000
    retry-delay-ms: 5000
  observability:
    correlation-header: X-Correlation-ID
    correlation-id-max-length: 128
server:
  port: ${SERVER_PORT:8080}
  forward-headers-strategy: framework
